import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易真的是一个反复试错的过程吗？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易是反复试错理解/交易核心规律.md","filePath":"stock/交易是反复试错理解/交易核心规律.md"}'),r={name:"stock/交易是反复试错理解/交易核心规律.md"};function s(n,p,c,i,_,d){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="交易真的是一个反复试错的过程吗" tabindex="-1">交易真的是一个反复试错的过程吗？ <a class="header-anchor" href="#交易真的是一个反复试错的过程吗" aria-label="Permalink to &quot;交易真的是一个反复试错的过程吗？&quot;">​</a></h1><p>试错思维又是一个典型误导人的大坑。</p><p>有试错思维，就陷入了概率思维。</p><p>试错和概率，都是让人赔的老逼朝天的狗屎理念。</p><p>试错和概率，都是让人赔的老逼朝天的狗屎理念。</p><p>试错和概率，都是让人赔的老逼朝天的狗屎理念。</p><p>为什么特朗普能当美国总统？？？看懂了这个视频，也就悟透了交易的核心。</p><p>看懂了吧，特朗普非常聪明，发现了小娃娃好像只会说最后一个词，然后又问了一遍，结果验证了自己的猜想，最后运用这个规律，问了一个想得到答案的问题。</p><p><strong>所以，交易的核心是发现规律，验证规律，运用规律，三步走，层层递进。</strong></p><p>1、交易的核心是发现规律，验证规律，运用规律。仅此而已，绝不是无脑的概率。</p><p>2、摒弃概率思维，否则它会成为你不思进取的借口。一直主张概率思维，你就不会深入细致的研究价格波动规律，反正一切都是概率，最终走向模糊和不确定，亏钱了又说是自己心态不好。</p><p>3、心态不好主要是因为老赔钱，心态是果，不是因，也就是说，心态好了，没技术，照样赔钱。</p><p>4、行情当然是确定的，都实实在在走出来，怎么是不确定的呢？！你不能把自己分析不出来行情走势等同于行情不确定，这完全是两码事。</p><p>5、人体内一个小小的鞭毛马达震惊了我们众人，结合现代量子力学、天文学等，让人不得不怀疑，整个宇宙都在按着某些规律无比精密、精巧地运转和演化。更何况如一粒尘埃的金融市场。</p><p>6、概率论只是人类认识自然和宇宙时，能力不足的无奈之举。不要开口就谈交易就是博大概率事件，哪怕谈概率，也是在深入研究价格波动规律基础之上的概率。</p><p>7、不管是基本面分析，还是量化，亦或者普通技术分析，都是研究的规律。比如基本面中的利率规律，比如量化中的成交量规律，比如传统技术分析中的突破规律，又比如阐释宏观价格波动结构的波浪规律。这一切都是围绕规律进行的。</p><p>8、不要过于美化止损，止损只是交易很微小的一部分，坚决止损不等于赚钱，哪怕仓位再轻，笔笔设止损，如果没有发现价格波动规律，必然是稳定的亏损，最终爆仓。</p><p>9、自己摸索，五年稳定盈利已经是天才，时间、精力和资金等沉默成本巨大，远不如跟一个已经成功的师傅学习效率高，且确定性强。</p><p>因为，成功才是成功之母，失败是成功的阻碍。只有世界冠军才能培养世界冠军。跟着成功人学，就是坐高铁飞机，高效、快速；自己摸索，呵呵，不多说。</p>',19)]))}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
